/* ========================================
   KOFISHOOP — JavaScript
   Interaktivitas & animasi
   ======================================== */

'use strict';

// =========================================
// 1. STICKY NAVIGATION
// =========================================
const navbar = document.getElementById('navbar');
const navToggle = document.getElementById('navToggle');
const navMenu = document.getElementById('navMenu');
const navLinks = document.querySelectorAll('.nav-link');

function updateNav() {
    if (window.scrollY > 80) {
        navbar.classList.add('scrolled');
    } else {
        navbar.classList.remove('scrolled');
    }
}

window.addEventListener('scroll', updateNav, { passive: true });
window.addEventListener('load', updateNav);

// =========================================
// 2. MOBILE HAMBURGER MENU
// =========================================
navToggle.addEventListener('click', () => {
    navToggle.classList.toggle('active');
    navMenu.classList.toggle('active');
});

// Tutup menu saat link diklik
navLinks.forEach(link => {
    link.addEventListener('click', () => {
        navToggle.classList.remove('active');
        navMenu.classList.remove('active');
    });
});

// Tutup menu saat klik di luar
document.addEventListener('click', (e) => {
    if (!navbar.contains(e.target) && navMenu.classList.contains('active')) {
        navToggle.classList.remove('active');
        navMenu.classList.remove('active');
    }
});

// =========================================
// 3. SMOOTH SCROLL (fallback untuk Safari)
// =========================================
document.querySelectorAll('a[href^="#"]').forEach(anchor => {
    anchor.addEventListener('click', function (e) {
        const href = this.getAttribute('href');
        if (href === '#') return;
        const target = document.querySelector(href);
        if (target) {
            e.preventDefault();
            const offset = navbar.offsetHeight;
            const targetPos = target.getBoundingClientRect().top + window.scrollY - offset;
            window.scrollTo({
                top: targetPos,
                behavior: 'smooth'
            });
        }
    });
});

// =========================================
// 4. ADVANCED SCROLL REVEAL — staggered + directional + scale
// =========================================
const allRevealElements = document.querySelectorAll('.reveal, .reveal-left, .reveal-right, .reveal-scale');

const revealObserver = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
        if (entry.isIntersecting) {
            // Add visible class with a small random delay for organic feel
            const delay = parseFloat(entry.target.dataset.delay) || 0;
            setTimeout(() => {
                entry.target.classList.add('visible');
            }, delay * 1000);
        }
    });
}, {
    threshold: 0.15,
    rootMargin: '0px 0px -80px 0px'
});

allRevealElements.forEach(el => revealObserver.observe(el));

// =========================================
// 4b. SCROLL PROGRESS INDICATOR
// =========================================
const scrollProgress = document.createElement('div');
scrollProgress.className = 'scroll-progress';
scrollProgress.innerHTML = '<div class="scroll-progress-bar" id="scrollProgressBar"></div>';
document.body.appendChild(scrollProgress);

function updateScrollProgress() {
    const scrollTop = window.scrollY;
    const docHeight = document.documentElement.scrollHeight - window.innerHeight;
    const progress = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;
    const bar = document.getElementById('scrollProgressBar');
    if (bar) bar.style.width = progress + '%';
}
window.addEventListener('scroll', updateScrollProgress, { passive: true });
window.addEventListener('load', updateScrollProgress);

// =========================================
// 5. VELOCITY SCROLLING — PARALLAX MULTI-LAYER
// =========================================
const heroBg = document.getElementById('heroBg');
const heroContent = document.querySelector('.hero-content');
const sectionAlts = document.querySelectorAll('.section-alt');
const serviceCards = document.querySelectorAll('.service-card');
const aboutImage = document.querySelector('.about-img-box');
const footer = document.querySelector('.footer');

let scrollVelocity = 0;
let lastScrollY = 0;
let rafId = null;

// Smooth parallax update dengan velocity easing
function updateParallax() {
    const scrolled = window.scrollY;
    const viewH = window.innerHeight;
    const isMobile = window.innerWidth <= 768;

    if (!isMobile) {
        // Hero background — gerak sangat lambat (10%) untuk depth maksimal
        heroBg.style.transform = `translateY(${scrolled * 0.1}px)`;

        // Hero content — gerak lebih cepat agar terasa depth
        heroContent.style.transform = `translateY(${scrolled * 0.12}px)`;

        // Section alt backgrounds — parallax lebih jelas
        sectionAlts.forEach(section => {
            const rect = section.getBoundingClientRect();
            const center = rect.top + rect.height / 2;
            const progress = center / viewH;
            if (progress > -0.5 && progress < 1.5) {
                const bgOffset = (progress - 0.5) * 20;
                section.style.backgroundPosition = `center ${50 + bgOffset}%`;
                section.style.backgroundSize = '110% auto';
            }
        });
    } else {
        heroBg.style.transform = 'translateY(0)';
        heroContent.style.transform = 'translateY(0)';
        sectionAlts.forEach(section => {
            section.style.backgroundPosition = 'center';
            section.style.backgroundSize = '';
        });
    }
}

// Velocity-based scroll: elemen bergerak dengan kecepatan berbeda
function velocityScroll() {
    const currentY = window.scrollY;
    scrollVelocity = currentY - lastScrollY;
    lastScrollY = currentY;

    if (window.innerWidth > 768) {
        // Service cards: gerak lebih responsif terhadap scroll
        serviceCards.forEach((card, i) => {
            const rect = card.getBoundingClientRect();
            if (rect.top < window.innerHeight && rect.bottom > 0) {
                const speed = 0.5 + (i * 0.15);
                const offset = scrollVelocity * speed * 0.5;
                card.style.transform = `translateY(${offset}px) scale(${1 + Math.abs(scrollVelocity) * 0.001})`;
                clearTimeout(card._velocityTimer);
                card._velocityTimer = setTimeout(() => {
                    card.style.transform = '';
                }, 200);
            }
        });

        // About image — efek velocity
        if (aboutImage) {
            const rect = aboutImage.getBoundingClientRect();
            if (rect.top < window.innerHeight && rect.bottom > 0) {
                const offset = scrollVelocity * 0.4;
                aboutImage.style.transform = `translateY(${offset}px)`;
                clearTimeout(aboutImage._velocityTimer);
                aboutImage._velocityTimer = setTimeout(() => {
                    aboutImage.style.transform = '';
                }, 200);
            }
        }
    }

    rafId = null;
}

// Gabungkan parallax + velocity dalam satu scroll handler
window.addEventListener('scroll', () => {
    updateParallax();

    // Velocity scroll via requestAnimationFrame
    if (!rafId) {
        rafId = requestAnimationFrame(velocityScroll);
    }
}, { passive: true });

// =========================================
// 6. TESTIMONI CAROUSEL
// =========================================
const carouselTrack = document.getElementById('carouselTrack');
const carouselDots = document.querySelectorAll('.carousel-dot');
const slides = document.querySelectorAll('.carousel-slide');
let currentSlide = 0;
let carouselInterval;

function goToSlide(index) {
    if (index < 0) index = slides.length - 1;
    if (index >= slides.length) index = 0;

    carouselTrack.style.transform = `translateX(-${index * 100}%)`;
    currentSlide = index;

    carouselDots.forEach(dot => dot.classList.remove('active'));
    carouselDots[index].classList.add('active');
}

function nextSlide() {
    goToSlide(currentSlide + 1);
}

function startCarousel() {
    stopCarousel();
    carouselInterval = setInterval(nextSlide, 5000);
}

function stopCarousel() {
    if (carouselInterval) {
        clearInterval(carouselInterval);
        carouselInterval = null;
    }
}

// Dot navigation
carouselDots.forEach(dot => {
    dot.addEventListener('click', () => {
        const slideIndex = parseInt(dot.getAttribute('data-slide'));
        goToSlide(slideIndex);
        resetCarousel();
    });
});

function resetCarousel() {
    stopCarousel();
    startCarousel();
}

// Pause on hover
const carousel = document.querySelector('.testimoni-carousel');
carousel.addEventListener('mouseenter', stopCarousel);
carousel.addEventListener('mouseleave', startCarousel);

// Touch support
let touchStartX = 0;
let touchEndX = 0;

carousel.addEventListener('touchstart', (e) => {
    touchStartX = e.changedTouches[0].screenX;
    stopCarousel();
}, { passive: true });

carousel.addEventListener('touchend', (e) => {
    touchEndX = e.changedTouches[0].screenX;
    const diff = touchStartX - touchEndX;
    if (Math.abs(diff) > 50) {
        if (diff > 0) goToSlide(currentSlide + 1);
        else goToSlide(currentSlide - 1);
    }
    startCarousel();
}, { passive: true });

// Init carousel
goToSlide(0);
startCarousel();

// =========================================
// 7. FORM HANDLING
// =========================================
const kontakForm = document.getElementById('kontakForm');
const formToast = document.getElementById('formToast');

kontakForm.addEventListener('submit', (e) => {
    e.preventDefault();

    const nama = document.getElementById('nama').value.trim();
    const email = document.getElementById('email').value.trim();
    const pesan = document.getElementById('pesan').value.trim();

    // Validasi
    if (!nama || !email || !pesan) {
        alert('请填写所有字段！');
        return;
    }

    // Validasi email sederhana
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email)) {
        alert('请输入有效的邮箱地址。');
        return;
    }

    // Tampilkan toast sukses
    formToast.classList.add('show');
    kontakForm.reset();

    // Sembunyikan toast setelah 5 detik
    setTimeout(() => {
        formToast.classList.remove('show');
    }, 5000);
});

// =========================================
// 8. LIGHTBOX GALERI
// =========================================
const galleryItems = document.querySelectorAll('.gallery-featured, .gallery-card');
const lightbox = document.getElementById('lightbox');
const lightboxClose = document.getElementById('lightboxClose');
const lightboxImg = document.getElementById('lightboxImg');
const lightboxCaption = document.getElementById('lightboxCaption');

const galleryData = [
    { img: 'images/gallery-1.jpg', label: '清晨咖啡香 — 每天的第一杯咖啡，唤醒你的学习灵魂' },
    { img: 'images/gallery-2.jpg', label: '拉花艺术 &amp; 风味' },
    { img: 'images/gallery-3.jpg', label: '学习氛围' },
    { img: 'images/gallery-4.jpg', label: '轻松喝咖啡' },
    { img: 'images/gallery-5.jpg', label: '讨论 &amp; 灵感' },
    { img: 'images/gallery-6.jpg', label: '最喜欢的角落' }
];

galleryItems.forEach((item, index) => {
    item.addEventListener('click', () => {
        const data = galleryData[index];
        lightboxImg.style.backgroundImage = `url('${data.img}')`;
        lightboxCaption.innerHTML = data.label;
        lightbox.classList.add('active');
        document.body.style.overflow = 'hidden';
        stopCarousel();
    });
});

function closeLightbox() {
    lightbox.classList.remove('active');
    document.body.style.overflow = '';
    startCarousel();
}

lightboxClose.addEventListener('click', closeLightbox);

// Tutup lightbox klik di luar konten
lightbox.addEventListener('click', (e) => {
    if (e.target === lightbox) {
        closeLightbox();
    }
});

// Tutup lightbox dengan tombol Escape
document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && lightbox.classList.contains('active')) {
        closeLightbox();
    }
});

// =========================================
// 10. COUNTER ANIMATION — about stats
// =========================================
function animateCounter() {
    document.querySelectorAll('.stat-number').forEach(el => {
        const target = parseInt(el.dataset.target);
        if (!target) return;
        const inc = Math.ceil(target / 60);
        let current = 0;
        const timer = setInterval(() => {
            current += inc;
            if (current >= target) {
                el.textContent = target;
                clearInterval(timer);
            } else {
                el.textContent = current;
            }
        }, 20);
    });
}

// Trigger counter on scroll reveal
const statObserver = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
        if (entry.isIntersecting) {
            animateCounter();
            statObserver.disconnect();
        }
    });
}, { threshold: 0.3 });

const statsSection = document.querySelector('.about-stats');
if (statsSection) statObserver.observe(statsSection);

// =========================================
// 11. GALLERY TAG FILTER
// =========================================
document.querySelectorAll('.gallery-tag').forEach(tag => {
    tag.addEventListener('click', function() {
        document.querySelectorAll('.gallery-tag').forEach(t => t.classList.remove('active'));
        this.classList.add('active');
    });
});

// =========================================
// 12. SERVICE TAB SWITCH
// =========================================
document.querySelectorAll('.service-tab').forEach(tab => {
    tab.addEventListener('click', function() {
        // Toggle tabs
        document.querySelectorAll('.service-tab').forEach(t => t.classList.remove('active'));
        this.classList.add('active');

        // Toggle panels
        const target = this.dataset.tab;
        document.querySelectorAll('.service-panel').forEach(p => p.classList.remove('active'));
        const panel = document.getElementById('panel-' + target);
        if (panel) panel.classList.add('active');
    });
});

// =========================================
// 13. RESIZE HANDLER
// =========================================
let resizeTimer;
window.addEventListener('resize', () => {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(() => {
        // Update parallax on resize
        updateParallax();
        // Re-check nav
        if (window.innerWidth > 768 && navMenu.classList.contains('active')) {
            navToggle.classList.remove('active');
            navMenu.classList.remove('active');
        }
    }, 250);
});

